% This test file was generated by Copilot. Validate generated output before use.
classdef TestSampleFlightRows < matlab.unittest.TestCase
    methods(Test)
        function testReturnsEmptyColumnVectorForZeroRows(testCase)
            % Verify that zero requested rows returns an empty column vector.
            actualRows = sampleFlightRows(0);

            testCase.verifyEqual(actualRows, zeros(0, 1));
            testCase.verifySize(actualRows, [0 1]);
        end

        function testReturnsSequentialRowsWhenUnderDefaultMaxSamples(testCase)
            % Verify that row indices are returned sequentially when sampling is unnecessary.
            numRows = 5;

            actualRows = sampleFlightRows(numRows);

            expectedRows = (1:numRows)';
            testCase.verifyEqual(actualRows, expectedRows);
        end

        function testReturnsAllRowsWhenEqualToMaxSamples(testCase)
            % Verify that all rows are returned when the number of rows equals the sample limit.
            numRows = 8;
            maxSamples = 8;

            actualRows = sampleFlightRows(numRows, maxSamples);

            expectedRows = (1:numRows)';
            testCase.verifyEqual(actualRows, expectedRows);
        end

        function testReturnsStableRoundedSamplesWhenAboveMaxSamples(testCase)
            % Verify that sampled indices are unique, ordered, and span the full row range.
            numRows = 100;
            maxSamples = 10;

            actualRows = sampleFlightRows(numRows, maxSamples);

            expectedRows = unique(round(linspace(1, numRows, maxSamples)))';
            testCase.verifyEqual(actualRows, expectedRows);
            testCase.verifyEqual(actualRows(1), 1);
            testCase.verifyEqual(actualRows(end), numRows);
            testCase.verifyTrue(issorted(actualRows));
            testCase.verifyEqual(numel(actualRows), numel(unique(actualRows)));
        end

        function testRejectsNegativeNumRows(testCase)
            % Verify that negative row counts are rejected by input validation.
            testCase.verifyError(@() sampleFlightRows(-1), ...
                'MATLAB:validators:mustBeNonnegative');
        end

        function testRejectsNonpositiveMaxSamples(testCase)
            % Verify that nonpositive maxSamples values are rejected by input validation.
            testCase.verifyError(@() sampleFlightRows(10, 0), ...
                'MATLAB:validators:mustBePositive');
        end
    end
end